    if capacity is None:
        cap_list = get_field(instance, ["vehicle_capacities"], None)
        if cap_list:
            capacity = cap_list[0]
    if capacity is None:
        capacity = sum(dem.get(i, 0) for i in ids) if ids else 0

    def demand_of(i):
        return dem.get(i, 0)

    def coord_of(i):
        return xy.get(i, (0.0, 0.0))

    dx0, dy0 = coord_of(depot_id)

    def dist(a, b):
        ax, ay = coord_of(a)
        bx, by = coord_of(b)
        dx = ax - bx
        dy = ay - by
        return (dx * dx + dy * dy) ** 0.5

    def angle_key(i):
        x, y = coord_of(i)
        return ((y - dy0) >= 0, (y - dy0) / (abs(x - dx0) + abs(y - dy0) + 1e-12), dist(depot_id, i), i)

    remaining = ids[:]
    remaining.sort(key=angle_key)

    routes = []
    while remaining:
        route = []
        load = 0
        last = depot_id
        while True:
            best = None
            best_key = None
            for i in remaining:
                d = demand_of(i)
                if load + d > capacity:
                    continue
                key = (dist(last, i), dist(depot_id, i), d, i)
                if best is None or key < best_key:
                    best = i
                    best_key = key
            if best is None:
                break
            route.append(best)
            load += demand_of(best)
            last = best
            remaining.remove(best)
        if not route:
            best = None
            best_key = None
            for i in remaining:
                key = (demand_of(i), dist(depot_id, i), i)
                if best is None or key < best_key:
                    best = i
                    best_key = key
            route = [best]
            remaining.remove(best)
        routes.append(route)

    def route_load(route):
        s = 0
        for i in route:
            s += demand_of(i)
        return s

    def route_length(route):
        if not route:
            return 0.0
        total = dist(depot_id, route[0])
        for a, b in zip(route, route[1:]):
            total += dist(a, b)
        total += dist(route[-1], depot_id)
        return total

    def nearest_order(route):
        unv = route[:]
        ordered = []
        cur = depot_id
        while unv:
            best = None
            best_key = None
            for i in unv:
                key = (dist(cur, i), dist(depot_id, i), i)
                if best is None or key < best_key:
                    best = i
                    best_key = key
            ordered.append(best)
            unv.remove(best)
            cur = best
        return ordered

    def two_opt(route):
        if len(route) < 4:
            return route[:]
        best = route[:]
        best_len = route_length(best)
        improved = True
        while improved:
            improved = False
            n = len(best)
            for i in range(n - 2):
                for j in range(i + 2, n):
                    if i == 0 and j == n - 1:
                        continue
                    cand = best[:i + 1] + best[i + 1:j + 1][::-1] + best[j + 1:]
                    cand_len = route_length(cand)
                    if cand_len + 1e-12 < best_len:
                        best = cand
                        best_len = cand_len
                        improved = True
                        break
                if improved:
                    break
        return best

    routes = [two_opt(nearest_order(r)) for r in routes]

    present = set()
    for r in routes:
        for c in r:
            present.add(c)

    for i in ids:
        if i not in present:
            placed = False
            for r in routes:
                if route_load(r) + demand_of(i) <= capacity:
                    best_pos = 0
                    best_delta = None
                    for p in range(len(r) + 1):
                        left = depot_id if p == 0 else r[p - 1]
                        right = depot_id if p == len(r) else r[p]
                        delta = dist(left, i) + dist(i, right) - dist(left, right)
                        if best_delta is None or (delta, p) < (best_delta, best_pos):
                            best_delta = delta
                            best_pos = p
                    r.insert(best_pos, i)
                    placed = True
                    present.add(i)
                    break
            if not placed:
                routes.append([i])
                present.add(i)

    final_routes = []
    for r in routes:
        if r:
            final_routes.append(two_opt(nearest_order(r)))

    return final_routes
